patch:
diff --git a/repro/report.js b/repro/report.js
new file mode 100644
index 0000000..bdd12af
--- /dev/null
+++ b/repro/report.js
@@ -0,0 +1,16 @@
+/* eslint no-useless-assignment: "warn" */
+
+async function fn() {
+  let intermediaryValue;
+  try {
+    intermediaryValue = 42;
+    unsafeFn();
+    return { error: undefined };
+  } catch {
+    return { intermediaryValue };
+  }
+}
+
+function unsafeFn() {
+  throw new Error();
+}
diff --git a/repro/run-report.js b/repro/run-report.js
new file mode 100644
index 0000000..223e1a9
--- /dev/null
+++ b/repro/run-report.js
@@ -0,0 +1,23 @@
+"use strict";
+// Reproduces eslint/eslint#19245 with the checkout's own Linter, using the reporter's config.
+const fs = require("node:fs");
+const path = require("node:path");
+const { Linter } = require("../lib/api");
+
+const code = fs.readFileSync(path.join(__dirname, "report.js"), "utf8")
+    .replace(/^\/\* eslint .*\*\/\n/u, "");
+const messages = new Linter({ configType: "flat" }).verify(
+    code,
+    [{ rules: { "no-useless-assignment": "warn" } }],
+    "report.js"
+);
+
+console.log(JSON.stringify(messages.map(m => ({ line: m.line, column: m.column, ruleId: m.ruleId, message: m.message })), null, 2));
+
+const falsePositive = messages.find(m => m.ruleId === "no-useless-assignment" && m.line === 5);
+if (falsePositive) {
+    console.log("\nBUG REPRODUCED: `intermediaryValue = 42` flagged although it is read in the catch block.");
+    process.exitCode = 1;
+} else {
+    console.log("\nNot reproduced: no no-useless-assignment report on the try-block assignment.");
+}
